import data from "./data.json"
import {
  Page,
  Section,
  Grid,
  Block,
  Text,
  Stat,
  DataTable,
  KV,
  FigureStrip,
  Figure,
  FigureImage,
  FigureLabel,
} from "@/components/report"

const totalIssues = data.issues.length

export default function Report() {
  // 结论项(问题总数)排在首位,其余指标按数据里的原顺序跟在后面
  const issues = data.kpis.find((k) => k.key === "issues")
  const kpis = issues
    ? [issues, ...data.kpis.filter((k) => k.key !== "issues")]
    : data.kpis

  return (
    <Page title={data.title} meta={[data.target, data.date]}>
      <Section title="结论" description={`按 ${data.standard} 评估`}>
        <Text className="text-2xl leading-9 font-light">
          {`${data.verdict}。${data.summary}`}
        </Text>
      </Section>

      <Section title="核心指标" description="本次检查的范围与结果">
        <Grid cols={kpis.length} fields={false} className="items-baseline">
          {kpis.map((k) =>
            k.key === "fail" ? (
              <Stat
                key={k.key}
                captionBelow
                size="lg"
                value={k.value}
                unit={k.unit}
                label={k.label}
                note="要求 ≥ 4.5:1"
                direction="down"
              />
            ) : (
              <Stat
                key={k.key}
                captionBelow
                size="lg"
                value={k.value}
                unit={k.unit}
                label={k.label}
              />
            )
          )}
        </Grid>
      </Section>

      <Section title="模拟视图" description="按 Machado 2009 模型模拟红色盲、绿色盲、蓝色盲">
        <Block title="色觉模拟" description="原界面与红色盲、绿色盲、蓝色盲模拟对照">
          <FigureStrip>
            {data.screens.map((s) => (
              <Figure key={s.view}>
                <FigureImage src={s.image} alt={s.view} />
                <FigureLabel>{s.view}</FigureLabel>
              </Figure>
            ))}

